import{G as a,b as r,c as e,ae as i}from"./chunks/framework.l_MR1ur9.js";const p=JSON.parse('{"title":"介绍","description":"","frontmatter":{"title":"介绍","date":"2024/04/15 20:49:57","author":"花木凋零成兰","tags":[],"categories":["设计模式"]},"headers":[],"relativePath":"DesignPatterns/介绍.md","filePath":"DesignPatterns/介绍.md","lastUpdated":1791630580000}'),l={name:"DesignPatterns/介绍.md"};function o(n,t,s,g,d,h){return r(),e("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1713214197000"},[...t[0]||(t[0]=[i('<h1 id="介绍" tabindex="-1">介绍 <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍&quot;">​</a></h1><h2 id="设计模式的重要性" tabindex="-1">设计模式的重要性 <a class="header-anchor" href="#设计模式的重要性" aria-label="Permalink to &quot;设计模式的重要性&quot;">​</a></h2><ol><li>软件工程中, <strong>设计模式</strong> 是对软件设计中普遍存在(反复出现)的各种问题,所提出的<strong>解决方案</strong>.</li><li>目前程序员门槛越来越高</li><li>接受维护项目; 即<strong>维护性</strong>[可读性, 规范性]</li><li>大厂提问: <strong>实际项目中使用过什么设计模式? 怎么使用的? 解决了什么问题?</strong></li></ol><h2 id="设计模式在软件中哪里" tabindex="-1">设计模式在软件中哪里? <a class="header-anchor" href="#设计模式在软件中哪里" aria-label="Permalink to &quot;设计模式在软件中哪里?&quot;">​</a></h2><p>面向对象(OO) =&gt; 功能模块[设计模式+数据结构] =&gt; 框架[使用到多种设计模式] =&gt; 架构[服务器集群]</p><h2 id="设计模式的目的" tabindex="-1">设计模式的目的 <a class="header-anchor" href="#设计模式的目的" aria-label="Permalink to &quot;设计模式的目的&quot;">​</a></h2><p>编写软件过程中,程序员面临着来自 <strong>耦合性</strong>, <strong>内聚性</strong>及<strong>可维护性</strong>,<strong>重用性</strong>,<strong>灵活性</strong>等多方面的挑战,设计模式是为了让程序(软件)具有更好的:</p><ol><li>代码重用性: 即相同功能的代码,不用多次编写</li><li>可读性: 即编程规范,便于其他程序员阅读和理解</li><li>可扩展性: 即增加新的功能时,非常方便</li><li>可靠性: 当增加新的功能时,对原来功能没有影响</li><li>使程序呈现 <strong>高内聚,低耦合</strong>的特性</li></ol><ul><li>金句:</li></ul><p>设计模式包含了面向对象的精髓，“懂了设计模式，你就懂了面向对象分析和设计（OOA/D）的精要”</p><p>Scott Mayers 在其巨著《Effective C++》就曾经说过：C++老手和 C++新手的区别就是前者手背上有很多伤疤</p><h2 id="设计模式常用七大原则" tabindex="-1">设计模式常用七大原则: <a class="header-anchor" href="#设计模式常用七大原则" aria-label="Permalink to &quot;设计模式常用七大原则:&quot;">​</a></h2><ul><li>单一职责原则</li><li>接口隔离原则</li><li>依赖倒转(倒置)原则</li><li>里氏代换原则</li><li>开闭原则ocp</li><li>迪米特原则</li><li>合成复用原则</li></ul><h2 id="设计模式分为三种类型" tabindex="-1">设计模式分为三种类型 <a class="header-anchor" href="#设计模式分为三种类型" aria-label="Permalink to &quot;设计模式分为三种类型&quot;">​</a></h2><p>共23种</p><ol><li>创建型模式：<strong>单例模式</strong>,抽象工厂模式,原型模式,建造者模式,<strong>工厂模式</strong>。</li><li>结构型模式：适配器模式,桥接模式,<strong>装饰模式</strong>,组合模式,外观模式,享元模式,<strong>代理模式</strong>。</li><li>行为型模式：模版方法模式,命令模式,访问者模式,迭代器模式,<strong>观察者模式</strong>,中介者模式,备忘录模式,解释器模式(Interpreter模式),状态模式,策略模式,职责链模式(责任链模式)</li></ol>',16)])])}const u=a(l,[["render",o]]);export{p as __pageData,u as default};
